const { seg, eio, eo, lerp } = kit;

kit.scene('sidebar-collapse', {
  init(kit) {
    const lockupUrl = W.logoLockupUrl(kit);
    const markUrl = W.logoMarkUrl(kit);
    const opts = ['A. POST', 'B. GET', 'C. PATCH', 'D. CONNECT', 'E. None of the above'];
    const optHtml = opts.map((label, i) => {
      const sel = i === 1;
      return '<div style="display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:6px;background:' +
        (sel ? 'var(--tint)' : 'transparent') + ';font-size:17px;line-height:24px;color:var(--main)">' +
        '<span class="ui-radio" style="border-color:' + (sel ? 'var(--accent)' : 'var(--second)') + '">' +
        (sel ? '<span class="ui-radio-dot"></span>' : '') + '</span>' +
        '<span>' + label + '</span></div>';
    }).join('');

    kit.stage.append(kit.h(
      '<div class="ground">' +
      W.studyChrome('1 · Desktop Sidebar Collapse', '272px to 64px rail', 'Context, selection, and scroll preserved') +
      '<div class="ui-window sidebar-collapse-win" style="left:160px;top:148px;width:1600px;height:824px;display:flex">' +
        '<aside class="sidebar-collapse-side" style="width:272px;flex-shrink:0;height:100%;box-sizing:border-box;background:var(--nav-bg);padding:16px 12px;display:flex;flex-direction:column;gap:18px;position:relative;overflow:hidden">' +
          '<div style="position:relative;height:44px;display:flex;align-items:center">' +
            '<img class="sidebar-collapse-lockup" src="' + lockupUrl + '" alt="Exam App" style="position:absolute;left:8px;top:8px;height:28px;width:auto"/>' +
            '<div class="sidebar-collapse-toggle" style="position:absolute;right:0;top:0;width:44px;height:44px;border-radius:6px;display:flex;align-items:center;justify-content:center;color:var(--main)">' +
              '<span class="sidebar-collapse-panel">' + W.panelSvg() + '</span>' +
              '<img class="sidebar-collapse-mark" src="' + markUrl + '" alt="Exam App mark" style="position:absolute;width:24px;height:24px;opacity:0"/>' +
            '</div>' +
          '</div>' +
          '<div style="display:flex;flex-direction:column;gap:6px">' +
            '<div style="height:44px;padding:0 12px;border-radius:6px;background:var(--tint);display:flex;align-items:center;gap:10px;color:var(--main)">' +
              '<span style="color:var(--accent);flex-shrink:0;display:flex">' + W.docSvg() + '</span>' +
              '<span class="sidebar-collapse-label1" style="font-size:15px;font-weight:600;white-space:nowrap">DATAPREV · 2026 · Analyst…</span>' +
            '</div>' +
            '<div style="height:44px;padding:0 12px;border-radius:6px;display:flex;align-items:center;gap:10px;color:var(--main)">' +
              '<span style="color:var(--second);flex-shrink:0;display:flex">' + W.docSvg() + '</span>' +
              '<span class="sidebar-collapse-label2" style="font-size:15px;font-weight:400;white-space:nowrap">PPSA · 2025 · Analyst…</span>' +
            '</div>' +
          '</div>' +
        '</aside>' +
        '<main style="flex:1;min-width:0;padding:36px 56px;box-sizing:border-box;display:flex;flex-direction:column;gap:26px">' +
          '<div style="display:flex;align-items:center;justify-content:space-between;max-width:740px">' +
            '<span style="font-size:15px;font-weight:600;color:var(--second)">DATAPREV · 2026 · Analyst · Page 1 of 5</span>' +
            '<span class="sidebar-collapse-state" style="font-size:14px;font-weight:600;color:var(--accent);background:var(--tint);padding:4px 10px;border-radius:6px">Sidebar: Expanded (272px)</span>' +
          '</div>' +
          '<div style="max-width:740px;display:flex;flex-direction:column;gap:12px">' +
            '<h2 style="margin:0;font-size:18px;font-weight:600;color:var(--main)">Question 1</h2>' +
            '<p style="margin:0;font-size:17px;line-height:25px;color:var(--main)">Which HTTP method is defined as safe and idempotent?</p>' +
            '<div style="display:flex;flex-direction:column;gap:4px">' + optHtml + '</div>' +
            '<div style="margin-top:8px;width:112px;height:44px;border-radius:6px;background:var(--accent);color:var(--on-brand);display:flex;align-items:center;justify-content:center;font-size:15px;font-weight:600">Answer</div>' +
          '</div>' +
          '<div style="max-width:740px;display:flex;flex-direction:column;gap:8px;padding-top:10px">' +
            '<h2 style="margin:0;font-size:18px;font-weight:600;color:var(--main)">Question 2</h2>' +
            '<p style="margin:0;font-size:17px;line-height:25px;color:var(--main)">Which SQL clause filters rows before grouping?</p>' +
          '</div>' +
        '</main>' +
      '</div>' +
      '<div class="sidebar-collapse-chip" style="position:absolute;left:1120px;top:860px;padding:12px 18px;border-radius:999px;background:var(--main);color:var(--ground);font-size:18px;font-weight:600;opacity:0">Selection &amp; scroll preserved across collapse</div>' +
      '</div>'
    ));

    const q = (s) => kit.stage.querySelector(s);
    this.side = q('.sidebar-collapse-side');
    this.lockup = q('.sidebar-collapse-lockup');
    this.toggle = q('.sidebar-collapse-toggle');
    this.panel = q('.sidebar-collapse-panel');
    this.mark = q('.sidebar-collapse-mark');
    this.l1 = q('.sidebar-collapse-label1');
    this.l2 = q('.sidebar-collapse-label2');
    this.stateBadge = q('.sidebar-collapse-state');
    this.chip = q('.sidebar-collapse-chip');

    this.cur = kit.cursor();
    this.cur.keys = [
      { t: 0.4, at: [640, 420] },
      { t: 1.15, at: [402, 186] },
      { t: 2.8, at: [520, 260] }
    ];
    this.cur.clicks = [1.35];
    this.cur.visible = (t) => seg(t, 0.2, 0.4) * (1 - seg(t, 3.8, 4.2));
  },
  render(t) {
    const hover = seg(t, 1.05, 1.25) * (1 - seg(t, 2.0, 2.2));
    const p = eio(seg(t, 1.5, 2.15));
    const w = lerp(272, 64, p);
    this.side.style.width = w.toFixed(1) + 'px';

    const labelFade = 1 - eo(seg(t, 1.5, 1.75));
    this.lockup.style.opacity = labelFade;
    this.l1.style.opacity = labelFade;
    this.l2.style.opacity = labelFade;

    const toMark = eo(seg(t, 2.0, 2.3));
    this.panel.style.opacity = 1 - toMark;
    this.mark.style.opacity = toMark;
    this.toggle.style.right = lerp(0, -2, p).toFixed(1) + 'px';
    this.toggle.style.background = hover > 0.1 ? 'var(--hover-bg)' : 'transparent';

    this.stateBadge.textContent = p > 0.5 ? 'Sidebar: Collapsed rail (64px)' : 'Sidebar: Expanded (272px)';

    const chipIn = eo(seg(t, 2.45, 2.85));
    this.chip.style.opacity = chipIn;
    this.chip.style.transform = 'translateY(' + lerp(12, 0, chipIn).toFixed(1) + 'px)';

    this.cur.render(t);
  }
});
